// Public group page. No sign-in required.
// Lists that group's published events (published_events: web directory, not hidden).
// Does not show a Meetup member count, rating, nearby events, or past events.
// /preview is a different route and is unchanged.
import { useEffect, useState } from 'react';
import { ActivityIndicator, Platform, Text, useWindowDimensions, View } from 'react-native';
import { router, Stack, useLocalSearchParams } from 'expo-router';
import { RichText } from '../../components/rich-text';
import { PublicEventLinkCard } from '../../components/events';
import { CoverBand } from '../../components/record-chrome';
import { PublicGroupSponsors } from '../../components/group-sponsors';
import { Button, EmptyState, ErrorText, Page, PersonFace, SectionCard, styles } from '../../components/ui';
import { rememberReturnPath } from '../../lib/auth';
import { PRODUCT_NAME } from '../../lib/config';
import { getPublishedGroup, listPublishedGroupEvents, listPublishedGroupOrganizers, listPublishedGroupSponsors } from '../../lib/groups';
import { organizerLabel, PUBLIC_GROUP_PAGE_WIDTH } from '../../lib/public-group';
import { useSession } from '../../lib/session';
import { colors, fs, viewportWidth } from '../../lib/theme';
import type { PublicEvent, PublicGroup, PublicGroupOrganizer, PublicGroupSponsor } from '../../lib/types';

const WIDE_AT = 960;
// react-native's ViewStyle omits sticky. react-native-web keeps the string and sticks the sidebar.
const sidebarStyle = {
  width: 300,
  flexShrink: 0,
  alignSelf: 'flex-start' as const,
  position: 'sticky' as 'relative',
  top: 16,
};

export default function PublicGroupPage() {
  const raw = useLocalSearchParams<{ slug: string }>().slug;
  const slug = Array.isArray(raw) ? raw[0] : raw;
  const { userId, loading } = useSession();
  const { width: windowWidth } = useWindowDimensions();
  const wide = Platform.OS === 'web' && viewportWidth(windowWidth) >= WIDE_AT;
  const [group, setGroup] = useState<PublicGroup | null | undefined>(undefined);
  const [events, setEvents] = useState<PublicEvent[] | null>(null);
  const [sponsors, setSponsors] = useState<PublicGroupSponsor[] | null>(null);
  const [organizers, setOrganizers] = useState<PublicGroupOrganizer[] | null>(null);
  const [coverBroken, setCoverBroken] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  useEffect(() => {
    if (!slug) { setGroup(null); return; }
    let live = true;
    setGroup(undefined); setErr(null); setEvents(null); setSponsors(null); setOrganizers(null); setCoverBroken(false);
    getPublishedGroup(slug).then(async (row) => {
      if (!live) return;
      setGroup(row);
      if (!row) return;
      const [listed, sponsorRows, organizerRows] = await Promise.all([
        listPublishedGroupEvents(row.id),
        listPublishedGroupSponsors(row.id),
        listPublishedGroupOrganizers(row.id),
      ]);
      if (!live) return;
      setEvents(listed);
      setSponsors(sponsorRows);
      setOrganizers(organizerRows);
    }).catch((e) => {
      if (!live) return;
      setErr(e?.message ?? 'Could not load this group.');
      setGroup(null);
    });
    return () => { live = false; };
  }, [slug]);

  const login = () => {
    const next = group ? `/groups/${group.id}` : '/groups';
    rememberReturnPath(next);
    router.push(`/sign-in?next=${encodeURIComponent(next)}`);
  };

  if (group === undefined && !err) return <View style={{ flex: 1, justifyContent: 'center' }}><ActivityIndicator color={colors.navy} /></View>;
  if (err) return <Page><ErrorText>{err}</ErrorText></Page>;
  if (!group) return (
    <Page>
      <Stack.Screen options={{ title: 'Group' }} />
      <EmptyState icon="people-outline" title="Group not found" body="This group isn’t available on the public page."
        action={!loading ? (userId
          ? <Button small variant="neutral" title="Open groups" onPress={() => router.push('/groups')} />
          : <Button small variant="neutral" title="Sign in" onPress={login} />) : undefined} />
    </Page>
  );

  const faces = (organizers ?? []).flatMap((person) => {
    const name = organizerLabel(person);
    return name ? [<PersonFace key={`${person.username ?? ''}:${name}`} name={name} path={person.avatar_path} size={36} />] : [];
  });

  const sidebar = (
    <View style={{ width: '100%', gap: 12 }}>
      {faces.length ? <View style={{ gap: 10 }}>{faces}</View> : null}
      {!loading ? (
        <Button title="Join this group" onPress={userId ? () => router.push(`/groups/${group.id}`) : login} style={{ width: '100%' }} />
      ) : null}
      {sponsors?.length ? <PublicGroupSponsors sponsors={sponsors} /> : null}
    </View>
  );

  const showCover = Boolean(group.image_url) && !coverBroken;
  // Full content width, then the serif title under the cover. The two-column body starts below that, on desktop and on a phone.
  const hero = (
    <View style={{ width: '100%', gap: 16 }}>
        {showCover ? <CoverBand url={group.image_url} onError={() => setCoverBroken(true)} /> : null}
      <View style={{ gap: 4 }}>
        <Text style={styles.eyebrow}>{PRODUCT_NAME}</Text>
        <Text accessibilityRole="header" style={[styles.h1, { fontSize: fs(wide ? 36 : 28), lineHeight: fs(wide ? 42 : 34) }]}>{group.name}</Text>
        {group.locality ? <Text style={[styles.muted, { fontSize: fs(15) }]}>{group.locality}</Text> : null}
      </View>
    </View>
  );

  return (
    <Page contentWidth={PUBLIC_GROUP_PAGE_WIDTH}>
      {/* Web header stays hidden. The serif title stays under the cover. */}
      <Stack.Screen options={{ title: group.name, headerShown: Platform.OS !== 'web' }} />
      {hero}
      <View style={{ flexDirection: wide ? 'row' : 'column', alignItems: 'flex-start', gap: 16, width: '100%' }}>
        {wide ? null : <View style={{ width: '100%' }}>{sidebar}</View>}
        <View style={{ flex: 1, minWidth: 0, width: wide ? undefined : '100%', gap: 16 }}>
          {group.description ? <SectionCard title="About"><RichText source={group.description} /></SectionCard> : null}
          <SectionCard title="Events" padded={false}>
            {events === null ? <View style={{ padding: 20 }}><ActivityIndicator color={colors.navy} /></View>
              : events.length === 0 ? <EmptyState icon="calendar-outline" title="No upcoming events" body="Published events in this group show up here." />
              : <View style={{ flexDirection: 'row', flexWrap: 'wrap', padding: 8 }}>
                  {events.map((event) => (
                    <View key={event.id} style={{ width: wide ? '50%' : '100%', padding: 6 }}>
                      <PublicEventLinkCard event={event} onPress={() => router.push(`/e/${event.id}`)} />
                    </View>
                  ))}
                </View>}
          </SectionCard>
        </View>
        {wide ? <View style={sidebarStyle}>{sidebar}</View> : null}
      </View>
    </Page>
  );
}
